      max-height: 80vh;
  }
  @media (max-width: 768px) {
      .video-container, .transcript-sidebar {
          flex: 100%;
      }
  }
  ```
- **Sentiment Color Coding**: Incorporate OpenAI’s teal/amber/white scheme for transcript lines and waveform based on sentiment (positive: teal, negative: amber, neutral: white).
  ```css
  .transcript-line.positive { color: #00d4aa; }
  .transcript-line.negative { color: #f5a623; }
  .transcript-line.neutral { color: #fff; }
  ```
- **Watch Source Button**: Style with Grok’s active state (amber background when enabled) and subtle hover effects.
  ```css
  #watchSource.enabled {
      background: #f5a623;
      color: #0a0a0a;
      cursor: pointer;
  }
  ```

#### 4. JavaScript (Real-time Interactivity)
- **Socket.IO Client**: Handle real-time transcript and sentiment updates with throttling to prevent UI lag.
  ```javascript
  const socket = io();
  let lastUpdate = 0;
  socket.on('transcript_update', (data) => {
      const now = Date.now();
      if (now - lastUpdate > 100) {  // Throttle updates
          updateTranscript(data.text, data.sentiment);
          updateSentimentWaveform(data.sentiment);
          updateWatchSource(data.partner);
          lastUpdate = now;
      }
  });
  ```
- **Sentiment Waveform**: Use Grok’s historical data approach with Chart.js for smoother animations, combined with OpenAI’s color coding.
  ```javascript
  const ctx = document.getElementById('sentimentCanvas').getContext('2d');
  const sentimentChart = new Chart(ctx, {
      type: 'line',
      data: { datasets: [{ data: [], borderColor: '#fff' }] },
      options: { responsive: true, maintainAspectRatio: false }
  });
  function updateSentimentWaveform(value) {
      sentimentChart.data.datasets[0].data.push(value);
      if (sentimentChart.data.datasets[0].data.length > 50) {
          sentimentChart.data.datasets[0].data.shift();
      }
      sentimentChart.data.datasets[0].borderColor = getSentimentColor(value);
      sentimentChart.update();
  }
  function getSentimentColor(value) {
      if (value > 0.3) return '#00d4aa'; // Positive
      if (value < -0.3) return '#f5a623'; // Negative
      return '#fff'; // Neutral
  }
  ```
- **Transcript Sidebar**: Implement auto-scrolling with a toggle (pause/resume) and color-coded lines.
  ```javascript
  let autoScroll = true;
  function updateTranscript(text, sentiment) {
      const line = document.createElement('p');
      line.className = `transcript-line ${sentiment > 0.3 ? 'positive' : sentiment < -0.3 ? 'negative' : 'neutral'}`;
      line.textContent = text;
      document.getElementById('transcriptContent').appendChild(line);
      if (autoScroll) line.scrollIntoView({ behavior: 'smooth' });
  }
  document.getElementById('toggleScroll').addEventListener('click', () => {
      autoScroll = !autoScroll;
      this.textContent = autoScroll ? 'Pause Scroll' : 'Resume Scroll';
  });
  ```
- **Watch Source Button**: Use OpenAI’s logic for enabling/disabling based on partner mentions, fetching URLs securely via API.
  ```javascript
  function updateWatchSource(partner) {
      const button = document.getElementById('watchSource');
      if (partner) {
          fetch(`/api/partner?url=${encodeURIComponent(partner)}`)
              .then(res => res.json())
              .then(data => {
                  button.disabled = false;
                  button.classList.add('enabled');
                  button.setAttribute('data-url', data.url);
                  button.setAttribute('title', `Watch ${partner}`);
              });
      } else {
          button.disabled = true;
          button.classList.remove('enabled');
      }
  }
  document.getElementById('watchSource').addEventListener('click', () => {
      window.open(this.getAttribute('data-url'), '_blank');
  });
  ```

#### 5. Error Handling and Performance
- **Socket.IO Disconnection Handling**: Notify users of connection loss and attempt reconnection.
  ```javascript
  socket.on('disconnect', () => {
      const warning = document.createElement('p');
      warning.textContent = 'Connection lost. Reconnecting...';
      document.getElementById('transcriptContent').appendChild(warning);
  });
  ```
- **Performance Optimization**: Throttle Socket.IO updates and limit transcript DOM elements to the last 100 lines to prevent memory issues.
  ```javascript
  function pruneTranscript() {
      const content = document.getElementById('transcriptContent');
      while (content.children.length > 100) {
